//  The indicator logic below is transplanted unchanged from QI_06_VRPProxy (indicators/QI_06_VRPProxy.cs);
//  its own documentation follows.
//
//  QI_06_VRPProxy - Volatility risk premium proxy: ATR(5) / ATR(14)
//
//  Lineage : split out of the "IBSFade" multi-strategy indicator, DataBox plot #13
//            (ORIG lines 1373-1377; atr14 = ATR(14) at 347, atr5 = ATR(5) at 414).
//  Provenance: ATR5/ATR14 is a practitioner proxy; the variance risk premium proper is implied minus
//            realized variance. No authoritative source for this proxy.
//  Concept : Short-vs-long realized volatility ratio ("DeltaInvariantVol" concept).
//  Formula : VRP = ATR5[0] / ATR14[0] when CurrentBar >= 20 && ATR14[0] > 0, else 1.0.
//  Quirks  : ORIG additionally gated its entire OnBarUpdate on CurrentBar >= 50 (so its
//            logged value was 1.0 before bar 50); only the per-signal guard is kept here.
// ============================================================================
#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Input;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Cbi;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.SuperDom;
using NinjaTrader.Gui.Tools;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.Core.FloatingPoint;
using NinjaTrader.NinjaScript.Indicators;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

// This namespace holds Strategies in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Strategies
{
	public class QS_06_VRPProxy : Strategy
	{
		private ATR		atr5;
		private ATR		atr14;
		private bool	disclaimerDrawn;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description					= "Volatility risk premium proxy: ATR(5) / ATR(14). 1.0 until bar 20 or when ATR14 is 0. "
											+ "Educational use only - not financial advice."
											+ " Backtest research strategy generated from QI_06_VRPProxy and backtest/rules.yaml. Not financial advice. Places no orders in real time unless Backtest Only is turned off.";
				Name						= "QS_06_VRPProxy";
				Calculate					= Calculate.OnBarClose;
				// Strategy defaults (backtest research; generated)
				EntriesPerDirection			= 1;
				EntryHandling				= EntryHandling.AllEntries;
				IsExitOnSessionCloseStrategy = false;
				StartBehavior				= StartBehavior.WaitUntilFlat;
				BarsRequiredToTrade			= 0;
				Slippage					= 1;
				DefaultQuantity				= 1;
				BacktestOnly				= true;
				TraceOrders					= false;
				IsOverlay					= false;
				DisplayInDataBox			= true;
				DrawOnPricePanel			= false;
				ScaleJustification			= ScaleJustification.Right;

				LowerThreshold				= 0.7;
				UpperThreshold				= 1.5;
				ShowDisclaimer				= false;

				AddPlot(new Stroke(Brushes.Teal, 2), PlotStyle.Line, "ATR5/ATR14");
				AddLine(Brushes.DodgerBlue, 0.7, "Lower Threshold");
				AddLine(Brushes.OrangeRed,  1.5, "Upper Threshold");
			}
			else if (State == State.Configure)
			{
				// BacktestOnly: never let NinjaTrader synchronise the account with its own orders (BT16).
				if (BacktestOnly)
					StartBehavior = StartBehavior.WaitUntilFlat;
				Lines[0].Value = LowerThreshold;
				Lines[1].Value = UpperThreshold;
			}
			else if (State == State.DataLoaded)
			{
				atr5			= ATR(5);
				atr14			= ATR(14);
				disclaimerDrawn	= false;
			}
		}

		private void QiUpdate()
		{
			// ORIG 1374-1375, verbatim.
			double vrpVal = CurrentBar >= 20 && atr14[0] > 0 ? atr5[0] / atr14[0] : 1.0;
			Values[0][0] = vrpVal;

			DrawDisclaimerOnce();
		}

		// ------------------------------------------------------------------------------
		//  Backtest rule (generated from backtest/rules.yaml - do not edit by hand)
		//  module VRPProxy | frame D | value vrp_proxy = VRPProxy[0] | ORIG lines 1374-1377
		//  long : x > 1.5
		//  short: x < 0.7
		// ------------------------------------------------------------------------------
		protected override void OnBarUpdate()
		{
			QiUpdate();
			ApplyRule();
		}

		// Backtest-only safety (validation/channel-a-backtest.md BT16): a Realtime-only guard is not
		// enough - an order submitted on the last historical bar carries into real time, and the
		// account-synchronising start behaviours make NinjaTrader place its own orders. With
		// BacktestOnly on, orders are allowed only during historical processing, only on the
		// Strategy Analyzer 'Backtest' account or a Sim/Playback account, and never on the last two
		// historical bars of a non-Backtest account; StartBehavior is forced to WaitUntilFlat.
		private bool OrdersAllowed()
		{
			if (State != State.Historical) return false;
			string acct = Account != null ? Account.Name : string.Empty;
			bool backtest = acct == "Backtest";
			bool research = backtest || acct.StartsWith("Sim") || acct.StartsWith("Playback");
			if (!research) return false;
			if (!backtest && CurrentBars[0] >= BarsArray[0].Count - 2) return false;
			return true;
		}

		private void ApplyRule()
		{
			if (BacktestOnly && !OrdersAllowed()) return;
			if (BarsInProgress != 0) return;

			double x = double.NaN;
			if (VRPProxy.IsValidDataPoint(0))
				x = VRPProxy[0];

			// A NaN / unset value maps to a flat target.
			int target = 0;
			if (!double.IsNaN(x))
			{
				bool goLong  = x > 1.5;
				bool goShort = x < 0.7;
				if (goLong)
					target = 1;
				else if (goShort)
					target = -1;
			}

			if (target == 1 && Position.MarketPosition != MarketPosition.Long)
				EnterLong(DefaultQuantity, "QS_L");
			else if (target == -1 && Position.MarketPosition != MarketPosition.Short)
				EnterShort(DefaultQuantity, "QS_S");
			else if (target == 0)
			{
				if (Position.MarketPosition == MarketPosition.Long)
					ExitLong("QS_XL", "QS_L");
				else if (Position.MarketPosition == MarketPosition.Short)
					ExitShort("QS_XS", "QS_S");
			}
		}

		private void DrawDisclaimerOnce()
		{
			if (!ShowDisclaimer || disclaimerDrawn)
				return;

			Draw.TextFixed(this, "QI_Disclaimer", "Educational use only - not financial advice",
				TextPosition.BottomLeft, Brushes.Gray, new SimpleFont("Arial", 9),
				Brushes.Transparent, Brushes.Transparent, 0);
			disclaimerDrawn = true;
		}

		public override string DisplayName
		{
			get { return "QS 06 VRPProxy"; }
		}

		#region Properties

		[NinjaScriptProperty]
		[Display(Name = "Backtest Only", Order = 0, GroupName = "Safety")]
		public bool BacktestOnly { get; set; }

		[NinjaScriptProperty]
		[Range(0.0, 10.0)]
		[Display(Name = "Lower Threshold", Description = "Reference line only. Original default 0.7.",
			Order = 1, GroupName = "Parameters")]
		public double LowerThreshold { get; set; }

		[NinjaScriptProperty]
		[Range(0.0, 10.0)]
		[Display(Name = "Upper Threshold", Description = "Reference line only. Original default 1.5.",
			Order = 2, GroupName = "Parameters")]
		public double UpperThreshold { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Show Disclaimer", Description = "Draw the educational-use disclaimer on the chart.",
			Order = 1, GroupName = "Display")]
		public bool ShowDisclaimer { get; set; }

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> VRPProxy
		{
			get { return Values[0]; }
		}

		#endregion
	}
}
